import {createRoot} from "react-dom/client";
import type {BusinessSettingsInput,BusinessSettingsRecord,DatabaseHealthReport,IssueReceiptInput,IssueReceiptResult,OnboardingStatus,PaymentMethod,ReceiptCoreStatus,ReceiptRecord,ReceiptSearchFilters,ReceiptSearchResult,CustomerRecord,CustomerProfile,CustomerCreateInput,CustomerUpdateInput,CustomerDuplicateMatch,DateRangeReport,AnnualReport,BackupOverview,BackupInspection,CloudSyncStatus,SupabaseCloudStatus,SupabaseCloudDevice,FullHealthReport,ErrorLogRecord,SecurityStatus,DiagnosticPreview,DiagnosticPackageResult,QaReport,QaExportResult,OpenFormatExportResult,SimulatorOfficialResultInput,SimulatorOfficialResultImport,TaxRegistrationDossierResult,ExpenseInput,ExpenseRecord,ExpenseSearchFilters,ExpenseSummary,ReceiptTemplateInput,ReceiptTemplateRecord} from "../../../../packages/database/src/types";
